'use client';
import { useEffect, useState } from 'react';
const api=async(u,o)=>{const r=await fetch(u,o);const d=await r.json();if(!r.ok)throw Error(d.error);return d};
export default function Home(){const [me,setMe]=useState(),[repos,setRepos]=useState([]),[chosen,setChosen]=useState([]),[filter,setFilter]=useState(''),[notice,setNotice]=useState(''),[modal,setModal]=useState(),[target,setTarget]=useState(''),[confirm,setConfirm]=useState('');const load=async()=>{const m=await api('/api/me');setMe(m);if(m.user)setRepos(await api('/api/repos'))};useEffect(()=>{load().catch(e=>setNotice(e.message))},[]);const toggle=n=>setChosen(x=>x.includes(n)?x.filter(a=>a!==n):[...x,n]);const run=async action=>{try{const d=await api('/api/bulk',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':me.csrf},body:JSON.stringify({action,repos:action==='unpinAll'?[]:chosen,target,confirmation:confirm})});const bad=d.results.filter(x=>!x.ok);setNotice(bad.length?`${d.results.length-bad.length} complete. ${bad.map(x=>x.error).join(' ')}`:`${d.results.length} repositories updated.`);setModal();setChosen([]);setTarget('');setConfirm('');await load()}catch(e){setNotice(e.message)}};const open=a=>{if(a==='unpinAll'||chosen.length)setModal(a);else setNotice('Select repositories first.')};const view=repos.filter(r=>r.full_name.toLowerCase().includes(filter.toLowerCase()));return <main><header><a className="brand" href="/"><span>⌁</span> gh-delete</a>{me?.user&&<div id="account"><img src={me.user.avatar_url} alt=""/><span>{me.user.login}</span><button onClick={()=>api('/api/auth/logout',{method:'POST'}).then(()=>location.reload())}>Sign out</button></div>}</header>{!me?.user?<section className="hero"><p className="eyebrow">Repository control, without the tab chaos</p><h1>Do the <em>big cleanup.</em><br/>Carefully.</h1><p className="lede">Select repositories and delete, pin, or transfer them in one deliberate batch.</p><a className="github" href="/api/auth/github">Continue with GitHub <b>→</b></a><p className="fine">Only repositories you own are shown. Delete always needs a second confirmation.</p></section>:<section id="workspace"><div className="toolbar"><div><p className="eyebrow">Your repositories</p><h2>{chosen.length} selected</h2></div><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filter repositories"/></div><div className="actions"><button onClick={()=>open('pin')}>Pin</button><button onClick={()=>open('unpin')}>Unpin selected</button><button onClick={()=>open('unpinAll')}>Unpin all</button><button onClick={()=>open('transfer')}>Transfer</button><button className="danger" onClick={()=>open('delete')}>Delete</button></div><div id="notice" className={notice.includes('complete')?'good':'bad'}>{notice}</div><div className="repos">{view.map(r=><label className="repo" key={r.id}><input type="checkbox" checked={chosen.includes(r.full_name)} onChange={()=>toggle(r.full_name)}/><span className="check"/><span className="repoInfo"><strong>{r.name}</strong><small>{r.owner} · {r.private?'Private':'Public'}{r.archived?' · Archived':''}</small>{r.description&&<i>{r.description}</i>}</span><time>{new Date(r.updated_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</time></label>)}</div></section>}{modal&&<div className="overlay"><div className="modal"><p className="eyebrow">{modal==='unpinAll'?'All pinned repositories':`${chosen.length} repositories selected`}</p><h2>{modal==='delete'?'Delete these repositories?':modal==='transfer'?'Transfer these repositories?':modal==='unpinAll'?'Unpin everything?':`${modal[0].toUpperCase()+modal.slice(1)} these repositories?`}</h2><p>{modal==='delete'?'This is permanent and cannot be undone.':modal==='transfer'?'This is the destination owner, not the owner you are transferring from.':modal==='unpinAll'?'Removes every repository currently pinned on your GitHub profile.':'GitHub will update the selected repositories.'}</p>{modal==='transfer'&&<label>Destination GitHub account or organization<input value={target} onChange={e=>setTarget(e.target.value)} placeholder="octo-org"/></label>}{modal==='delete'&&<label>Type DELETE to continue<input value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="DELETE"/></label>}<div className="modalActions"><button onClick={()=>setModal()}>Cancel</button><button className={modal==='delete'?'danger':''} onClick={()=>run(modal)}>Continue</button></div></div></div>}</main>}
